#include "../../includes/handlers/getType.hpp"

//This is only for static hander
// If the response body comes from a file → use MIME detection
// If the response body is generated by the server → hardcode Content-Type

std::string getType::getMimeType(const std::string &filePath)
{
    size_t dotPos = filePath.rfind('.');
    if (dotPos == std::string::npos)
        return "application/octet-stream";

    std::string ext = filePath.substr(dotPos + 1);
    if (ext == "html" || ext == "htm")
        return "text/html";
    else if (ext == "css")
        return "text/css";
    else if (ext == "js")
        return "application/javascript";
    else if (ext == "jpg" || ext == "jpeg")
        return "image/jpeg";
    else if (ext == "png")
        return "image/png";
    else if (ext == "gif")
        return "image/gif";
    else if (ext == "txt")
        return "text/plain";
    else if (ext == "json")
        return "application/json";
    else if (ext == "xml")
        return "application/xml";
    else if (ext == "pdf")
        return "application/pdf";
    else if (ext == "svg")
        return "image/svg+xml";
    else if (ext == "ico")
        return "image/x-icon";
    else if (ext == "woff" || ext == "woff2")
        return "font/woff";
    else if (ext == "ttf")
        return "font/ttf";
    else if (ext == "mp4")
        return "video/mp4";
    else if (ext == "webm")
        return "video/webm";
    else if (ext == "mp3")
        return "audio/mpeg";
    else if (ext == "wav")
        return "audio/wav";
    else
        return "application/octet-stream";
}